package com.careerguidance.controller;
import com.careerguidance.dto.request.RejectionRequest; import com.careerguidance.dto.response.*; import com.careerguidance.service.MentorVerificationService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/mentors") @PreAuthorize("hasRole('ADMIN')") public class AdminMentorVerificationController { private final MentorVerificationService service; private final com.careerguidance.repository.MentorProfileRepository profiles; private final com.careerguidance.repository.UserRepository users; public AdminMentorVerificationController(MentorVerificationService s,com.careerguidance.repository.MentorProfileRepository p,com.careerguidance.repository.UserRepository u){service=s;profiles=p;users=u;} @GetMapping("/pending") public List<MentorProfileResponse> pending(){return service.pending();} @GetMapping public List<MentorProfileResponse> all(){return profiles.findAll().stream().map(p->service.detail(p.getId())).toList();} @GetMapping("/{id}") public MentorProfileResponse detail(@PathVariable Long id){return service.detail(id);} @PostMapping("/{id}/approve") public MessageResponse approve(@PathVariable Long id,Authentication a){return service.approve(id,a.getName());} @PostMapping("/{id}/reject") public MessageResponse reject(@PathVariable Long id,@Valid @RequestBody RejectionRequest r,Authentication a){return service.reject(id,r,a.getName());} @PatchMapping("/{id}/activate") public MentorProfileResponse activate(@PathVariable Long id){return setActive(id,true);}@PatchMapping("/{id}/deactivate") public MentorProfileResponse deactivate(@PathVariable Long id){return setActive(id,false);} private MentorProfileResponse setActive(Long id,boolean active){var p=profiles.findById(id).orElseThrow(()->new com.careerguidance.exception.ResourceNotFoundException("Mentor profile not found: "+id));p.getUser().setActive(active);users.save(p.getUser());return service.detail(id);} @GetMapping("/statistics") public Map<String,Long> stats(){return service.statistics();} }
